<script setup lang="ts">
import { computed, ref } from 'vue'
import * as ops from '@/api/ops'
import { useUserStore } from '@/stores/user'
import { useAppStore } from '@/stores/app'
import { usePolling } from '@/composables/usePolling'
import { useChart } from '@/utils/echarts'
import StatCard from '@/components/StatCard.vue'
import OpsPageHeader from '@/components/OpsPageHeader.vue'
import PageState from '@/components/PageState.vue'
import WorkspaceIntro from './WorkspaceIntro.vue'
import { hasModulePermission } from '@/utils/authPolicy'
const user = useUserStore(), app = useAppStore(), data = ref<any>(null), timeline = ref<any[]>([]), autoRefresh = ref(true), trendEl = ref<HTMLElement|null>(null)
function canRead(module:string){return hasModulePermission(user.perms,module,'read')}
function fmt(value: unknown, digits = 2) { return value == null || value === '' || !Number.isFinite(Number(value)) ? '—' : Number(value).toLocaleString('zh-CN',{maximumFractionDigits:digits}) }
function colorPct(value: unknown) { return value == null ? 'var(--ops-sub)' : Number(value) > 85 ? 'var(--ops-danger)' : Number(value) > 70 ? 'var(--ops-warning)' : 'var(--ops-success)' }
function colorPctReverse(value: unknown) { return value == null ? 'var(--ops-sub)' : Number(value) < 15 ? 'var(--ops-danger)' : Number(value) < 30 ? 'var(--ops-warning)' : 'var(--ops-success)' }
function formatTime(value: unknown) { return value ? String(value).replace('T',' ') : '—' }
async function load() { const result = await ops.overview(); if (!result || typeof result !== 'object') throw new Error('概览数据格式异常，请重试'); data.value = result }
const {loading,error,updatedAt,stale,refresh} = usePolling(load,{interval:15000,enabled:autoRefresh})
const {loading:trendLoading,error:trendError,stale:trendStale,refresh:refreshTrend} = usePolling(async () => { if (!canRead('ops.metrics')) return; const result = await ops.httpTimeline(120); timeline.value = Array.isArray(result) ? result : result?.timeline || [] },{interval:15000,enabled:autoRefresh})
async function refreshAll() { await Promise.allSettled([refresh(),refreshTrend()]) }
const healthState = computed(() => data.value?.health?.status)
const healthLabel = computed(() => ({UP:'服务运行正常',DEGRADED:'部分检查需要关注',DOWN:'服务异常，请及时处理'}[healthState.value as string] || '健康状态未知'))
const healthColor = computed(() => data.value?.health?.score == null ? 'var(--ops-sub)' : Number(data.value.health.score) >= 80 ? 'var(--ops-success)' : Number(data.value.health.score) >= 60 ? 'var(--ops-warning)' : 'var(--ops-danger)')
const checkLabels: Record<string,string> = {database:'数据库',redis:'Redis',disk:'磁盘',heap:'JVM 堆',jvmHeap:'JVM 堆',aiPending:'AI 队列',aiFailureRate1h:'AI 失败率',dbPool:'连接池',httpError:'HTTP',cpu:'CPU'}
const onlineCount = computed(() => Array.isArray(data.value?.instances) ? data.value.instances.filter((row:any) => row.status === 'UP').length : '—')
const uptime = computed(() => { const ms = data.value?.app?.uptimeMs; if (ms == null) return '—'; const minutes = Math.floor(Number(ms)/60000); return minutes >= 1440 ? `${Math.floor(minutes/1440)} 天 ${Math.floor(minutes%1440/60)} 小时` : minutes >= 60 ? `${Math.floor(minutes/60)} 小时 ${minutes%60} 分钟` : `${minutes} 分钟` })
const resources = computed(() => [{label:'JVM 堆内存',value:data.value?.core?.heapUsedPct,color:colorPct(data.value?.core?.heapUsedPct),note:'使用率 · 建议保持 85% 以下'},{label:'系统内存',value:data.value?.core?.memUsedPct,color:colorPct(data.value?.core?.memUsedPct),note:'主机物理内存使用率'},{label:'磁盘剩余',value:data.value?.core?.diskFreePct,color:colorPctReverse(data.value?.core?.diskFreePct),note:'可用容量 · 低于 15% 需关注'}])
const chartOption = computed(() => { const dark = app.theme === 'dark', text = dark ? '#9caaa8' : '#8a918c', line = dark ? '#344044' : '#eeeee8'; return {grid:{left:36,right:12,top:16,bottom:24},tooltip:{trigger:'axis',backgroundColor:dark?'#263034':'#fff',textStyle:{color:dark?'#e8edeb':'#252a2e',fontSize:12},borderColor:line},xAxis:{type:'category',boundaryGap:false,data:timeline.value.map(p => new Date(p.time).toLocaleTimeString('zh-CN',{hour12:false})),axisLine:{show:false},axisTick:{show:false},axisLabel:{color:text,fontSize:12,interval:Math.max(0,Math.floor(timeline.value.length/5))}},yAxis:{type:'value',minInterval:1,axisLabel:{color:text,fontSize:12},splitLine:{lineStyle:{color:line,type:'dashed'}}},series:[{name:'请求量',type:'line',smooth:true,symbol:'none',lineStyle:{width:2,color:'#438c80'},areaStyle:{color:'#438c80',opacity:.08},data:timeline.value.map(p => p.count)},{name:'错误请求',type:'line',smooth:true,symbol:'none',lineStyle:{width:1.8,color:'#d98973'},data:timeline.value.map(p => p.errors)}]} })
useChart(trendEl,chartOption)
</script>
